  (1, '#fffdf6', '/tin/bg-trang.webp', '[{"id":"t12","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"TRONG SỐ NÀY","fontSize":44,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.2},{"id":"t13","type":"text","x":60,"y":157,"w":680,"rotation":0,"content":"Bản tin nội bộ của Uỷ ban MTTQ Việt Nam phường Yên Nghĩa","fontSize":21,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":false,"italic":true,"align":"center","lineHeight":1.5},{"id":"t14","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"03    Công bố quyết định thành lập Ban Công tác Mặt trận và các chi hội đoàn thể","fontSize":25,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t15","type":"text","x":60,"y":309,"w":680,"rotation":0,"content":"04    Triển khai nhiệm vụ trọng tâm, hướng về cơ sở, chăm lo nhân dân","fontSize":25,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t16","type":"text","x":60,"y":395,"w":680,"rotation":0,"content":"05    Tri ân người có công nhân kỷ niệm Ngày Thương binh — Liệt sĩ 27/7","fontSize":25,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t17","type":"text","x":60,"y":481,"w":680,"rotation":0,"content":"06    Tuyên truyền, vận động giải phóng mặt bằng","fontSize":25,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t18","type":"text","x":60,"y":532,"w":680,"rotation":0,"content":"07    Công đoàn và các hội quần chúng","fontSize":25,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t19","type":"text","x":60,"y":583,"w":680,"rotation":0,"conten